insert into admin_roles(name,description) values ('Super Administrator','Protected owner role'),('Event Manager','Events and inventory'),('Finance Manager','Orders and payment verification'),('Membership Manager','Membership and service reviews') on conflict do nothing;
insert into admin_permissions(code,description) values ('events.write','Create and edit events'),('events.publish','Publish event listings'),('inventory.write','Manage event inventory'),('orders.read','View order requests'),('payments.read','View payments'),('payments.verify','Verify manual payments'),('memberships.read','View applications'),('memberships.write','Review applications'),('services.read','View service requests'),('services.write','Manage service requests'),('admins.manage','Manage administrators'),('audit.read','View audit logs') on conflict do nothing;
insert into admin_role_permissions(role_id,permission_id) select r.id,p.id from admin_roles r cross join admin_permissions p where r.name='Super Administrator' on conflict do nothing;
insert into admin_role_permissions(role_id,permission_id) select r.id,p.id from admin_roles r join admin_permissions p on p.code in('events.write','events.publish','inventory.write','orders.read') where r.name='Event Manager' on conflict do nothing;
insert into admin_role_permissions(role_id,permission_id) select r.id,p.id from admin_roles r join admin_permissions p on p.code in('orders.read','payments.read','payments.verify','audit.read') where r.name='Finance Manager' on conflict do nothing;
insert into admin_role_permissions(role_id,permission_id) select r.id,p.id from admin_roles r join admin_permissions p on p.code in('memberships.read','memberships.write','services.read','services.write') where r.name='Membership Manager' on conflict do nothing;
